add_action( 'woocommerce_before_calculate_totals', 'perfectpixel_bulk_quantity_pricing', 20 );

function perfectpixel_bulk_quantity_pricing( $cart ) {
	if ( is_admin() && ! wp_doing_ajax() ) {
		return;
	}
	// Minimum quantity => discount %. Highest matching tier wins.
	$tiers = array(
		10  => 5,
		50  => 10,
		100 => 15,
	);
	$only_products = array(); // Empty = all products.
	krsort( $tiers );

	foreach ( $cart->get_cart() as $item ) {
		if ( $only_products && ! in_array( (int) $item['product_id'], $only_products, true ) ) {
			continue;
		}
		foreach ( $tiers as $min_qty => $percent ) {
			if ( $item['quantity'] >= $min_qty ) {
				$base = (float) $item['data']->get_price( 'edit' );
				$item['data']->set_price( $base * ( 100 - $percent ) / 100 );
				break;
			}
		}
	}
}
